from solution import minPath
import pytest
from hypothesis import given, HealthCheck
import hypothesis.strategies as st


# ---------- helpers (obviously-correct reference) ----------

def _neighbors(N, x, y):
    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nx, ny = x + dx, y + dy
        if 0 <= nx < N and 0 <= ny < N:
            yield nx, ny


def _pos_of(grid, v):
    N = len(grid)
    for i in range(N):
        for j in range(N):
            if grid[i][j] == v:
                return (i, j)
    raise AssertionError("value not found")


def _is_valid_walk(grid, vals):
    N = len(grid)
    if len(vals) == 0:
        return False
    # find all cells matching vals[0]
    starts = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == vals[0]]
    if not starts:
        return False
    cur_set = set(starts)
    for v in vals[1:]:
        nxt_set = set()
        for (x, y) in cur_set:
            for nx, ny in _neighbors(N, x, y):
                if grid[nx][ny] == v:
                    nxt_set.add((nx, ny))
        if not nxt_set:
            return False
        cur_set = nxt_set
    return True


def brute_min_path(grid, k):
    N = len(grid)
    best = None
    # DFS from every start; k is kept small by callers
    def dfs(x, y, path):
        nonlocal best
        if best is not None:
            # prune: if prefix already greater, stop
            # compare prefix of path vs best prefix
            if path > best[:len(path)]:
                return
        if len(path) == k:
            if best is None or path < best:
                best = list(path)
            return
        for nx, ny in _neighbors(N, x, y):
            path.append(grid[nx][ny])
            dfs(nx, ny, path)
            path.pop()
    for i in range(N):
        for j in range(N):
            dfs(i, j, [grid[i][j]])
    return best


def true_min_neighbor_of_one(grid):
    N = len(grid)
    x, y = _pos_of(grid, 1)
    return min(grid[nx][ny] for nx, ny in _neighbors(N, x, y))


# ---------- explicit spec examples ----------

def test_spec_example_1():
    assert minPath([[1, 2, 3], [4, 5, 6], [7, 8, 9]], 3) == [1, 2, 1]


def test_spec_example_2():
    assert minPath([[5, 9, 3], [4, 1, 6], [7, 8, 2]], 1) == [1]


# ---------- targeted regression for wrap-around defect ----------

def test_left_edge_wrap_must_not_count():
    # 1 at (0,0); true neighbours are 9 and 8 -> min 8.
    # grid[0][-1] == 2 is NOT a neighbour but buggy code reads it via y-1 == -1.
    grid = [
        [1, 9, 2],
        [8, 7, 6],
        [5, 4, 3],
    ]
    assert minPath(grid, 2) == [1, 8]
    assert minPath(grid, 3) == [1, 8, 1]
    assert minPath(grid, 4) == [1, 8, 1, 8]


def test_left_edge_wrap_middle_row():
    # 1 at (1,0); wrap cell (1,2)==2 is not adjacent.
    grid = [
        [9, 8, 7],
        [1, 6, 2],
        [5, 4, 3],
    ]
    # neighbours of 1: (0,0)=9, (2,0)=5, (1,1)=6 -> min 5
    assert minPath(grid, 2) == [1, 5]
    assert minPath(grid, 3) == [1, 5, 1]


def test_one_at_top_left_corner_small():
    grid = [
        [1, 4, 3],
        [6, 5, 2],
        [7, 8, 9],
    ]
    # neighbours: 4, 6 -> min 4
    assert minPath(grid, 3) == [1, 4, 1]


# ---------- properties ----------

small_grids = st.shared(
    st.integers(min_value=2, max_value=3),
    key="n",
)


def grid_strategy(n):
    return st.permutations(list(range(1, n * n + 1))).map(
        lambda p: [list(p[i * n:(i + 1) * n]) for i in range(n)]
    )


@given(n=st.integers(min_value=2, max_value=3))
def test_output_length_equals_k(n):
    grid = [[((i * n + j) % (n * n)) + 1 for j in range(n)] for i in range(n)]
    for k in [1, 2, 3, 5, 10]:
        assert len(minPath(grid, k)) == k


@given(
    n=st.integers(min_value=2, max_value=3),
    k=st.integers(min_value=1, max_value=6),
)
def test_first_element_is_one_property(n, k):
    import random
    # deterministic grid from seed-ish values: use sorted rotation
    vals = list(range(1, n * n + 1))
    # build a deterministic pseudo-random permutation from n,k
    rnd = random.Random(n * 100 + k)
    rnd.shuffle(vals)
    grid = [vals[i * n:(i + 1) * n] for i in range(n)]
    assert minPath(grid, k)[0] == 1


@given(
    n=st.integers(min_value=2, max_value=3),
    k=st.integers(min_value=1, max_value=5),
)
def test_valid_walk_and_values_in_range(n, k):
    import random
    rnd = random.Random(n * 1000 + k * 17 + 5)
    vals = list(range(1, n * n + 1))
    rnd.shuffle(vals)
    grid = [vals[i * n:(i + 1) * n] for i in range(n)]
    out = minPath(grid, k)
    assert len(out) == k
    assert all(1 <= v <= n * n for v in out)
    assert _is_valid_walk(grid, out), f"output {out} is not a walk on {grid}"


@given(
    n=st.integers(min_value=2, max_value=3),
    k=st.integers(min_value=2, max_value=5),
)
def test_second_element_is_min_neighbor_of_one(n, k):
    import random
    rnd = random.Random(n * 77 + k * 31 + 1)
    vals = list(range(1, n * n + 1))
    rnd.shuffle(vals)
    grid = [vals[i * n:(i + 1) * n] for i in range(n)]
    out = minPath(grid, k)
    assert out[1] == true_min_neighbor_of_one(grid)


@given(
    n=st.integers(min_value=2, max_value=3),
    k=st.integers(min_value=1, max_value=4),
)
def test_equivalence_to_brute_force(n, k):
    import random
    rnd = random.Random(n * 131 + k * 19 + 7)
    vals = list(range(1, n * n + 1))
    rnd.shuffle(vals)
    grid = [vals[i * n:(i + 1) * n] for i in range(n)]
    assert minPath(grid, k) == brute_min_path(grid, k)


def test_brute_force_all_2x2_k2():
    # exhaustively check every placement of 1..4 for k=2: catches edge bugs
    import itertools
    for perm in itertools.permutations([1, 2, 3, 4]):
        grid = [list(perm[0:2]), list(perm[2:4])]
        assert minPath(grid, 2) == brute_min_path(grid, 2)


def test_k1_always_singleton_one():
    assert minPath([[2, 1], [3, 4]], 1) == [1]
    assert minPath([[4, 3], [2, 1]], 1) == [1]
    assert minPath([[1, 2, 3], [4, 5, 6], [7, 8, 9]], 1) == [1]
